"""80 labeled options: 24 photo subjects and 56 abstract illustrated choices.
Unordered pair IDs provide 3,160 combinations, not 3,160 handwritten prompts.
"""
PHOTO_LABELS=('ကော်ဖီ','ရေနွေးကြမ်း','ပီဇာ','ဘာဂါ','မုန့်ဟင်းခါး','ရှမ်းခေါက်ဆွဲ','ချောကလက်ရေခဲမုန့်','ဗနီလာရေခဲမုန့်','သရက်သီး','ပန်းသီး','ဖရဲသီး','ငှက်ပျောသီး','ကြောင်','ခွေး','ယုန်','ကြက်တူရွေး','ပင်လယ်ကမ်းခြေ','တောင်တန်း','စာဖတ်ခြင်း','ဂိမ်းဆော့ခြင်း','ရုပ်ရှင်ကြည့်ခြင်း','စခန်းချခြင်း','စက်ဘီးစီးခြင်း','ဂစ်တာတီးခြင်း')
CONCEPT_LABELS='မနက်ခင်းအေးအေး|ညနေခင်းအေးအေး|မိုးရွာသံနားထောင်ခြင်း|ကြယ်တွေကြည့်ခြင်း|နေထွက်ချိန်ကြည့်ခြင်း|နေဝင်ချိန်ကြည့်ခြင်း|အိမ်မှာအနားယူခြင်း|သူငယ်ချင်းတွေနဲ့အပြင်ထွက်ခြင်း|တစ်ယောက်တည်းခရီးသွားခြင်း|အဖွဲ့လိုက်ခရီးသွားခြင်း|ခရီးတိုမကြာခဏသွားခြင်း|ခရီးရှည်တစ်ခါသွားခြင်း|မြို့ကြီးမှာနေခြင်း|ရွာအေးအေးမှာနေခြင်း|ပုံဆွဲခြင်း|ဓာတ်ပုံရိုက်ခြင်း|သီချင်းဆိုခြင်း|ကခုန်ခြင်း|ပီယာနိုတီးခြင်း|ဒရမ်တီးခြင်း|ဟင်းချက်ခြင်း|မုန့်ဖုတ်ခြင်း|ပန်းစိုက်ခြင်း|အိမ်မွေးတိရစ္ဆာန်စောင့်ရှောက်ခြင်း|အဖွဲ့လိုက်ဂိမ်းဆော့ခြင်း|တစ်ယောက်တည်းဂိမ်းဆော့ခြင်း|ပဟေဠိဖြေခြင်း|ဗဟုသုတပြိုင်ပွဲဆော့ခြင်း|စွန့်စားခန်းဂိမ်းဆော့ခြင်း|ဗျူဟာဂိမ်းဆော့ခြင်း|ကစားသမားနဲ့ပြိုင်ခြင်း|အတူပူးပေါင်းဆော့ခြင်း|ဟာသကားကြည့်ခြင်း|စွန့်စားခန်းကားကြည့်ခြင်း|ကာတွန်းကြည့်ခြင်း|မှတ်တမ်းရုပ်ရှင်ကြည့်ခြင်း|ဝတ္ထုဖတ်ခြင်း|ကာတွန်းစာအုပ်ဖတ်ခြင်း|စက္ကူစာအုပ်ဖတ်ခြင်း|အသံစာအုပ်နားထောင်ခြင်း|ဘာသာစကားအသစ်သင်ခြင်း|တူရိယာအသစ်သင်ခြင်း|ပရိုဂရမ်ရေးသင်ခြင်း|ဒီဇိုင်းသင်ခြင်း|ကြိုတင်အစီအစဉ်ဆွဲခြင်း|စိတ်ကူးပေါက်ရာလုပ်ခြင်း|ငွေစုခြင်း|ခရီးအတွက်ငွေသုံးခြင်း|လက်ရေးစာပို့ခြင်း|အသံမက်ဆေ့ချ်ပို့ခြင်း|လက်ဆောင်လုပ်ပေးခြင်း|လက်ဆောင်ဝယ်ပေးခြင်း|ဘောလုံးကစားခြင်း|ကြက်တောင်ရိုက်ခြင်း|ရေကူးခြင်း|တောင်တက်ခြင်း'.split('|')
OPTIONS=tuple({'id':i,'label':label,'photo':i if i<24 else None} for i,label in enumerate((*PHOTO_LABELS,*CONCEPT_LABELS)))
assert len(OPTIONS)==80 and len({o['label'] for o in OPTIONS})==80
PAIRS=tuple((a,b) for a in range(len(OPTIONS)) for b in range(a+1,len(OPTIONS)))
CAPACITY=len(PAIRS)
def question(index):
    a,b=PAIRS[index]
    from core.customization import message_text
    def option(i):
        value=dict(OPTIONS[i]);value['label']=message_text('msg.data.this_or_that.option.'+str(i),value['label'],{})
        return value
    return {'id':'TOT1-'+str(index),'a':option(a),'b':option(b)}
